**Automated Compliance Checker using Terraform**
=====================================================

This Terraform configuration creates an AWS Lambda function that periodically reads the Terraform state file, extracts resource configurations, and posts a compliance report to an external audit platform.

**Prerequisites**
-----------------

*   AWS account with necessary permissions
*   Terraform state file stored in an S3 bucket
*   External audit platform API endpoint and credentials

**Terraform Configuration**
---------------------------

### `main.tf`
```terraform
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
}

# Create an S3 bucket to store the Terraform state file
resource "aws_s3_bucket" "terraform_state" {
  bucket = "my-terraform-state-bucket"
  acl    = "private"

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }
}

# Create an IAM role for the Lambda function
resource "aws_iam_role" "lambda_role" {
  name        = "compliance-checker-lambda-role"
  description = "Execution role for the compliance checker Lambda function"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Effect = "Allow"
      }
    ]
  })
}

# Create an IAM policy for the Lambda function
resource "aws_iam_policy" "lambda_policy" {
  name        = "compliance-checker-lambda-policy"
  description = "Policy for the compliance checker Lambda function"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
        ]
        Resource = "${aws_s3_bucket.terraform_state.arn}/*"
        Effect    = "Allow"
      },
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
        ]
        Resource = "arn:aws:logs:*:*:*"
        Effect    = "Allow"
      }
    ]
  })
}

# Attach the IAM policy to the Lambda role
resource "aws_iam_role_policy_attachment" "lambda_attach" {
  role       = aws_iam_role.lambda_role.name
  policy_arn = aws_iam_policy.lambda_policy.arn
}

# Create the Lambda function
resource "aws_lambda_function" "compliance_checker" {
  filename      = "compliance_checker.zip"
  function_name = "compliance-checker"
  handler       = "index.handler"
  runtime       = "nodejs18.x"
  role          = aws_iam_role.lambda_role.arn

  environment {
    variables = {
      AUDIT_PLATFORM_API_ENDPOINT = "https://example.com/api/compliance-report"
      AUDIT_PLATFORM_API_KEY     = "your_api_key_here"
      TERRAFORM_STATE_BUCKET     = aws_s3_bucket.terraform_state.id
      TERRAFORM_STATE_KEY        = "terraform.tfstate"
    }
  }
}

# Create a CloudWatch event rule to trigger the Lambda function periodically
resource "aws_cloudwatch_event_rule" "compliance_checker_schedule" {
  name                = "compliance-checker-schedule"
  schedule_expression = "cron(0 0 * * ? *)" # Run daily at midnight UTC
}

# Create a CloudWatch event target to invoke the Lambda function
resource "aws_cloudwatch_event_target" "compliance_checker_target" {
  rule      = aws_cloudwatch_event_rule.compliance_checker_schedule.name
  target_id = "compliance-checker"
  arn       = aws_lambda_function.compliance_checker.arn
}

# Grant the CloudWatch event rule permission to invoke the Lambda function
resource "aws_lambda_permission" "compliance_checker_permission" {
  statement_id  = "AllowExecutionFromCloudWatch"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.compliance_checker.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.compliance_checker_schedule.arn
}
```

### `index.js` (Lambda function code)
```javascript
const AWS = require('aws-sdk');
const axios = require('axios');

const s3 = new AWS.S3({ region: 'us-west-2' });

exports.handler = async (event) => {
  try {
    // Read the Terraform state file from S3
    const terraformState = await s3.getObject({
      Bucket: process.env.TERRAFORM_STATE_BUCKET,
      Key: process.env.TERRAFORM_STATE_KEY,
    }).promise();

    // Parse the Terraform state file
    const state = JSON.parse(terraformState.Body.toString());

    // Extract resource configurations
    const resources = state.resources;

    // Create a compliance report
    const report = {
      resources: resources.map((resource) => ({
        type: resource.type,
        name: resource.name,
        attributes: resource.instances[0].attributes,
      })),
    };

    // Post the compliance report to the external audit platform
    const response = await axios.post(process.env.AUDIT_PLATFORM_API_ENDPOINT, report, {
      headers: {
        'Authorization': `Bearer ${process.env.AUDIT_PLATFORM_API_KEY}`,
      },
    });

    console.log(`Compliance report posted successfully: ${response.status}`);

    return {
      statusCode: 200,
      body: JSON.stringify({ message: 'Compliance report posted successfully' }),
    };
  } catch (error) {
    console.error(`Error posting compliance report: ${error.message}`);

    return {
      statusCode: 500,
      body: JSON.stringify({ message: 'Error posting compliance report' }),
    };
  }
};
```

**Usage**
---------

1.  Create a new directory for your Terraform project and navigate to it in your terminal/command prompt.
2.  Create a `main.tf` file and paste the provided Terraform configuration into it.
3.  Replace the placeholders (`your_api_key_here`, `https://example.com/api/compliance-report`) with your actual audit platform API key and endpoint.
4.  Create a new file named `index.js` and paste the provided Lambda function code into it.
5.  Run `terraform init` to initialize the Terraform working directory.
6.  Run `terraform apply` to create the AWS resources defined in the `main.tf` file.
7.  Package the Lambda function code into a ZIP file using `zip compliance_checker.zip index.js`.
8.  Update the `aws_lambda_function` resource in `main.tf` to point to the `compliance_checker.zip` file.
9.  Run `terraform apply` again to update the Lambda function code.

**Note**: Make sure to handle secrets securely in your Terraform state file and Lambda function environment variables. Consider using a secrets manager like AWS Secrets Manager or HashiCorp's Vault.

