**CI/CD Pipeline Diagnostic Tool**
=====================================

**Overview**
------------

The CI/CD pipeline diagnostic tool is designed to help developers troubleshoot failed builds by collecting relevant information from the runner and generating a diagnostic report. The tool will collect environment variables, mounted volumes, network configuration, and accessible API endpoints, and then upload the report to our support portal.

**Tool Requirements**
--------------------

* Python 3.8+
* `requests` library for API interactions
* `json` library for data serialization
* `subprocess` library for executing system commands

**Diagnostic Tool Code**
------------------------

```python
import os
import json
import requests
import subprocess

class DiagnosticTool:
    def __init__(self, support_portal_url, api_token):
        self.support_portal_url = support_portal_url
        self.api_token = api_token

    def collect_environment_variables(self):
        """Collects all environment variables"""
        return dict(os.environ)

    def collect_mounted_volumes(self):
        """Collects information about mounted volumes"""
        try:
            output = subprocess.check_output(['df', '-h']).decode('utf-8')
            return output.strip().split('\n')
        except subprocess.CalledProcessError as e:
            return f"Error collecting mounted volumes: {e}"

    def collect_network_configuration(self):
        """Collects network configuration information"""
        try:
            output = subprocess.check_output(['ip', 'addr', 'show']).decode('utf-8')
            return output.strip().split('\n')
        except subprocess.CalledProcessError as e:
            return f"Error collecting network configuration: {e}"

    def collect_accessible_api_endpoints(self):
        """Collects information about accessible API endpoints"""
        try:
            # Replace with your API endpoint list
            api_endpoints = ['https://api.example.com/healthcheck', 'https://api.example.com/status']
            results = []
            for endpoint in api_endpoints:
                response = requests.get(endpoint)
                results.append({
                    'endpoint': endpoint,
                    'status_code': response.status_code,
                    'response': response.text
                })
            return results
        except requests.RequestException as e:
            return f"Error collecting API endpoints: {e}"

    def generate_diagnostic_report(self):
        """Generates a diagnostic report"""
        report = {
            'environment_variables': self.collect_environment_variables(),
            'mounted_volumes': self.collect_mounted_volumes(),
            'network_configuration': self.collect_network_configuration(),
            'accessible_api_endpoints': self.collect_accessible_api_endpoints()
        }
        return json.dumps(report, indent=4)

    def upload_report_to_support_portal(self, report):
        """Uploads the diagnostic report to the support portal"""
        headers = {'Authorization': f"Bearer {self.api_token}"}
        response = requests.post(self.support_portal_url, headers=headers, data=report)
        if response.status_code == 201:
            print("Diagnostic report uploaded successfully")
        else:
            print(f"Error uploading diagnostic report: {response.text}")

def main():
    support_portal_url = 'https://support.example.com/api/diagnostic-reports'
    api_token = 'your_api_token_here'
    diagnostic_tool = DiagnosticTool(support_portal_url, api_token)
    report = diagnostic_tool.generate_diagnostic_report()
    diagnostic_tool.upload_report_to_support_portal(report)

if __name__ == '__main__':
    main()
```

**Usage**
---------

1. Replace `support_portal_url` and `api_token` with your actual support portal URL and API token.
2. Run the diagnostic tool using `python diagnostic_tool.py`.
3. The tool will generate a diagnostic report and upload it to the support portal.

**Example Diagnostic Report**
-----------------------------

```json
{
    "environment_variables": {
        "PATH": "/usr/local/bin:/usr/bin:/bin",
        "HOME": "/home/user",
        "LANG": "en_US.UTF-8"
    },
    "mounted_volumes": [
        "Filesystem      Size  Used Avail Use% Mounted on",
        "/dev/sda1       40G   12G   26G  31% /",
        "tmpfs           3.9G     0  3.9G   0% /dev/shm"
    ],
    "network_configuration": [
        "1: lo: <LOOPBACK,UP,LOWER_UP> mtu 65536 qdisc noqueue state UNKNOWN group default qlen 1000",
        "    link/loopback 00:00:00:00:00:00 brd 00:00:00:00:00:00",
        "    inet 127.0.0.1/8 scope host lo",
        "       valid_lft forever preferred_lft forever"
    ],
    "accessible_api_endpoints": [
        {
            "endpoint": "https://api.example.com/healthcheck",
            "status_code": 200,
            "response": "{\"status\":\"healthy\"}"
        },
        {
            "endpoint": "https://api.example.com/status",
            "status_code": 200,
            "response": "{\"status\":\"ok\"}"
        }
    ]
}
```

This diagnostic report provides a comprehensive overview of the runner's environment, including environment variables, mounted volumes, network configuration, and accessible API endpoints. The report can be used to troubleshoot failed builds and identify potential issues.

