**Automated IAM Policy Audit Script for AWS**
=====================================================

This script is designed to audit IAM policies in an AWS account. It enumerates all users, roles, and policies, tests which permissions are actually enforced, and generates a compliance report.

**Prerequisites**
-----------------

*   AWS CLI installed and configured with credentials that have sufficient permissions to perform IAM operations.
*   Python 3.8 or later installed.
*   Boto3 library installed (`pip install boto3`)

**Script**
----------

```python
import boto3
import json
from datetime import datetime

# Initialize AWS IAM client
iam = boto3.client('iam')

def enumerate_users():
    """Enumerate all IAM users."""
    users = []
    response = iam.list_users()
    users.extend(response['Users'])
    while 'IsTruncated' in response and response['IsTruncated']:
        response = iam.list_users(Marker=response['Marker'])
        users.extend(response['Users'])
    return users

def enumerate_roles():
    """Enumerate all IAM roles."""
    roles = []
    response = iam.list_roles()
    roles.extend(response['Roles'])
    while 'IsTruncated' in response and response['IsTruncated']:
        response = iam.list_roles(Marker=response['Marker'])
        roles.extend(response['Roles'])
    return roles

def enumerate_policies():
    """Enumerate all IAM policies."""
    policies = []
    response = iam.list_policies(Scope='All')
    policies.extend(response['Policies'])
    while 'IsTruncated' in response and response['IsTruncated']:
        response = iam.list_policies(Scope='All', Marker=response['Marker'])
        policies.extend(response['Policies'])
    return policies

def test_permissions(entity, entity_type):
    """Test permissions for an IAM entity."""
    if entity_type == 'user':
        try:
            # Attempt to create temporary admin credentials
            response = iam.create_access_key(UserName=entity['UserName'])
            access_key_id = response['AccessKey']['AccessKeyId']
            secret_access_key = response['AccessKey']['SecretAccessKey']
            # Test admin permissions
            test_iam = boto3.client('iam', aws_access_key_id=access_key_id, aws_secret_access_key=secret_access_key)
            test_iam.list_users()
            # If we reach this point, the user has admin permissions
            return {'entity': entity['UserName'], 'permissions': 'admin'}
        except Exception as e:
            # If an exception occurs, the user does not have admin permissions
            return {'entity': entity['UserName'], 'permissions': 'limited'}
        finally:
            # Clean up temporary admin credentials
            try:
                iam.delete_access_key(UserName=entity['UserName'], AccessKeyId=access_key_id)
            except Exception as e:
                pass
    elif entity_type == 'role':
        try:
            # Assume the role and test admin permissions
            sts = boto3.client('sts')
            response = sts.assume_role(RoleArn=entity['Arn'], RoleSessionName='TestSession')
            test_iam = boto3.client('iam', aws_access_key_id=response['Credentials']['AccessKeyId'], aws_secret_access_key=response['Credentials']['SecretAccessKey'], aws_session_token=response['Credentials']['SessionToken'])
            test_iam.list_users()
            # If we reach this point, the role has admin permissions
            return {'entity': entity['RoleName'], 'permissions': 'admin'}
        except Exception as e:
            # If an exception occurs, the role does not have admin permissions
            return {'entity': entity['RoleName'], 'permissions': 'limited'}

def generate_compliance_report(users, roles, policies):
    """Generate a compliance report."""
    report = {'users': [], 'roles': [], 'policies': []}
    for user in users:
        report['users'].append(test_permissions(user, 'user'))
    for role in roles:
        report['roles'].append(test_permissions(role, 'role'))
    for policy in policies:
        report['policies'].append({'policy': policy['PolicyName'], 'arn': policy['Arn']})
    return report

def main():
    users = enumerate_users()
    roles = enumerate_roles()
    policies = enumerate_policies()
    report = generate_compliance_report(users, roles, policies)
    with open('iam_compliance_report.json', 'w') as f:
        json.dump(report, f, indent=4)
    print('Compliance report generated: iam_compliance_report.json')

if __name__ == '__main__':
    main()
```

**Usage**
---------

1.  Save the script to a file (e.g., `iam_audit.py`).
2.  Install the required libraries by running `pip install boto3`.
3.  Configure your AWS CLI credentials.
4.  Run the script using `python iam_audit.py`.
5.  The script will generate a compliance report in JSON format and save it to a file named `iam_compliance_report.json`.

**Example Output**
------------------

The compliance report will contain information about the permissions of each IAM user and role, as well as a list of all IAM policies.

